import json
PATHS_TEXT = "{\"customerNo\": [[\"data\", \"customerNo\"], \"string\"], \"aiFlow\": [[\"data\", \"aiFlow\"], \"string\"], \"ani\": [[\"call\", \"ani\"], \"string\"], \"lang\": [[\"call\", \"lang\"], \"string\"]}"
FN = "cards_list"
FNS_TEXT = "[\"cards_balance\", \"cards_list\", \"contact_email_get\", \"statement_pdf_send\", \"statement_week_change\", \"statement_week_decide\", \"statement_week_get\"]"
MODEL_TEXT = "[\"ani\"]"

try:
    import json
    PATHS = json.loads(PATHS_TEXT)
    b = config.get('body') if isinstance(config, dict) and isinstance(config.get('body'), dict) else dict()
    out = dict()
    sent = dict()
    ALL_FNS = json.loads(FNS_TEXT)
    MODEL_FIELDS = json.loads(MODEL_TEXT)
    def tail(x):
        return ''.join(c for c in str(x) if c.isalnum())[-4:]
    def head(x):
        t = ''
        for c in str(x).strip():
            if not c.isalnum():
                break
            t += c
        return t
    for k in PATHS:
        path = PATHS[k][0]
        kind = PATHS[k][1]
        v = b.get(k)
        if v is None or chr(123) in str(v):
            continue
        # an identifier an earlier answer of this call gave must be sent exactly as given: when what the model wrote is not one of the
        # values seen for this field, it is replaced by the one seen value it matches (same last four characters, and the same start if several do)
        try:
            known = json.loads(str(vars.get('ff_seen_' + path[-1]) or '[]'))
        except Exception:
            known = []
        if known and str(v) not in known:
            same = [x for x in known if len(tail(v)) == 4 and tail(x) == tail(v)]
            if len(same) > 1:
                near = [x for x in same if head(x) and head(v) and (head(x).startswith(head(v)) or head(v).startswith(head(x)))]
                same = near if len(near) == 1 else same
            if len(same) == 1:
                v = same[0]
            elif len(known) == 1:
                v = known[0]                 # the bank gave exactly one value for this field in this call
        elif not known and isinstance(v, str) and len(v.strip()) >= 8:
            # no answer has a field of this name: a text the model wrote that ends like exactly one text the bank gave (and is not itself one) is that text, retyped
            every = []
            for fn in ALL_FNS:
                try:
                    for x in json.loads(str(vars.get('ff_any_' + fn) or '[]')):
                        if x not in every:
                            every.append(x)
                except Exception:
                    pass
            if every and v not in every:
                def common(a, b):
                    n = 0
                    while n < len(a) and n < len(b) and a[len(a) - 1 - n].lower() == b[len(b) - 1 - n].lower():
                        n += 1
                    return n
                close = [x for x in every if common(x, v) >= 8]
                if len(close) == 1:
                    v = close[0]
        if kind in ('number', 'integer'):
            try:
                v = float(str(v).replace(',', '.'))
                if kind == 'integer' or v == int(v):
                    v = int(v)
            except Exception:
                pass
        node = out
        for seg in path[:-1]:
            if not isinstance(node.get(seg), dict):
                node[seg] = dict()
            node = node[seg]
        node[path[-1]] = v
        sent[k] = v
    config['body'] = out
    vars['ff_req_' + FN] = ', '.join(str(k) + ' ' + str(sent[k]) for k in sent if k in MODEL_FIELDS)
    vars['ff_reqj_' + FN] = json.dumps(sent)
except Exception:
    pass

