import json
FN = "cards_balance"
NAME = "cards.balance"
HAS_DIGEST = True
NOW_VAR = "now"
FIELDS_TEXT = "[\"aiFlow\", \"ani\", \"cardNumber\", \"currencyType\", \"customerNo\", \"emailAddress\", \"intAddressInfoType\", \"lang\", \"newStatementWeek\", \"statementDate\", \"statementDay\"]"
OWN_TEXT = "[\"ani\", \"cardNumber\", \"lang\"]"

import re, datetime, math
def _digest(answer, request, now):
    d = answer.get('data') if isinstance(answer, dict) else None
    res = answer.get('result') if isinstance(answer, dict) else None
    rq = request if isinstance(request, dict) else dict()
    if isinstance(rq.get('data'), dict): rq = rq.get('data')
    if not isinstance(d, dict) or not d or (isinstance(res, dict) and str(res.get('returnCode', '1')) != '1'):
        return 'SERVICE FAILED (cards.balance). Say exactly: “Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.” Then CALL wrap_up(). Say no amount and no date.'
    ON = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    TE = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
    MO = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    def w(n):
        n = min(int(n), 999999999999)
        if n <= 0: return 'sıfır'
        out = []
        for val, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin'), (1, '')):
            q = n // val
            n = n % val
            if q == 0: continue
            if val == 1000 and q == 1:
                out.append('bin')
                continue
            if q // 100: out.extend(([] if q // 100 == 1 else [ON[q // 100]]) + ['yüz'])
            if (q // 10) % 10: out.append(TE[(q // 10) % 10])
            if q % 10: out.append(ON[q % 10])
            if name: out.append(name)
        return ' '.join(out)
    def num(v):
        try:
            x = float(str(v).replace(',', '.'))
            return x if x == x and abs(x) < 1e12 else 0.0
        except Exception:
            return 0.0
    def suf(s):
        v = 'i'
        for ch in reversed(s.lower()):
            if ch in 'aıeioöuü':
                v = 'ı' if ch in 'aı' else 'i' if ch in 'ei' else 'u' if ch in 'ou' else 'ü'
                break
        return chr(39) + ('t' if s[-1:] in 'fstkçşhp' else 'd') + v + 'r'
    def dt(s):
        m = re.match(r'^\s*(\d{1,2})\.(\d{1,2})\.(\d{4})\s*$', str(s or ''))
        if not m or not 1 <= int(m.group(2)) <= 12: return None
        return (int(m.group(3)), int(m.group(2)), int(m.group(1)))
    def say(t): return str(t[2]) + ' ' + MO[t[1] - 1] + ' ' + str(t[0])
    m = re.match(r'\s*(\d{4})-(\d{2})-(\d{2})', str(now or ''))
    today = (int(m.group(1)), int(m.group(2)), int(m.group(3))) if m else None
    cnum = str(rq.get('cardNumber') or '').strip()
    l4 = str(d.get('cardNumberLast4') or '').strip() or cnum[-4:]
    name = str(d.get('productName') or '').strip()
    card = 'Sonu ' + ' '.join(ON[int(x)] for x in l4 if x in '0123456789') + ' ile biten ' + (name + ' ' if name else '')
    debts = []
    clear = []
    totals = []
    tltot = ''
    auto = ''
    for key, nm, unit, sub, full in (('debtTL', 'Türk Lirası', 'lira', 'kuruş', 'Türk Lirası'), ('debtUSD', 'Dolar', 'dolar', 'sent', 'dolar'), ('debtEUR', 'Euro', 'Euro', 'sent', 'Euro'), ('debtGBP', 'İngiliz Sterlini', 'İngiliz Sterlini', 'peni', 'İngiliz Sterlini')):
        b = d.get(key)
        if not isinstance(b, dict) or not b: continue
        def A(f):
            c = int(round(abs(num(b.get(f))) * 100))
            if c % 100 == 0: return w(c // 100) + ' ' + full
            if c // 100 == 0: return w(c % 100) + ' ' + sub
            return w(c // 100) + ' ' + unit + ' ' + w(c % 100) + ' ' + sub
        if num(b.get('totalDebt')) > 0: totals.append(nm + ' toplam borcunuz ' + A('totalDebt') + suf(A('totalDebt')) + '.')
        if key == 'debtTL':
            tltot = A('totalDebt') if num(b.get('totalDebt')) > 0 else ''
            auto = A('remainAutomaticPaymentAmount') if num(b.get('remainAutomaticPaymentAmount')) > 0 else ''
        if num(b.get('remainingDebt')) <= 0:
            clear.append(nm)
            continue
        rmin = num(b.get('remainingMinPayment'))
        if key != 'debtTL': s = nm + ' borcunuz ' + A('statementDebt') + ', kalan toplam borcunuz ' + A('remainingDebt') + ', ödenmesi gereken minimum tutar ' + A('minPayment') + suf(A('minPayment')) + '.'
        elif rmin <= 0: s = 'Türk Lirası borcunuz ' + A('statementDebt') + ', kalan toplam borcunuz ' + A('remainingDebt') + suf(A('remainingDebt')) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
        elif rmin >= num(b.get('minPayment')): s = 'Türk Lirası borcunuz ' + A('statementDebt') + ', ödenmesi gereken minimum tutar ' + A('minPayment') + suf(A('minPayment')) + '.'
        else: s = 'Türk Lirası borcunuz ' + A('statementDebt') + ', ödenmesi gereken minimum tutar ' + A('minPayment') + ', kalan toplam borcunuz ' + A('remainingDebt') + ', kalan minimum ödeme tutarınız ' + A('remainingMinPayment') + suf(A('remainingMinPayment')) + '.'
        debts.append(s)
    sd = dt(d.get('statementDate'))
    ld = dt(d.get('lastPayDate'))
